#include "stdafx.h"#include <rsuIsType.h>#include <locale.h>#include <float.h>bool IsFlt(const char* ptr){  //static lconv* conv = localeconv();  struct lconv* conv = localeconv();  char dp = conv->decimal_point[0];  if ( dp != '.' )  {    const char* p = strchr( ptr, '.' );    if ( p != NULL ) dp = '.';  }  //  while ( *ptr == ' ' ) ptr++;  if ( *ptr == '-' ) ptr++;  else    if ( *ptr == '+' ) ptr++;  //  bool bFloat = false;  bool bSymbol = false;  while ( *ptr )  {    if ( *ptr == ' ' && bSymbol )    {      while ( *ptr == ' ' ) ptr++;      return *ptr == 0;    }    //    if ( ('e' == *ptr || *ptr == 'E') && bSymbol )    {      ptr++;      if ( *ptr == 0  ) return false;      if ( *ptr == 32 ) return false;      return IsInt(ptr);    }    //    if ( *ptr == dp )    {      if ( bFloat )        return false;      bFloat = true;      ptr++;      continue;    }    //    if ( !('0' <= *ptr && *ptr <= '9') )      return false;    bSymbol = true;    ptr++;  }  return bSymbol;}bool IsInt(const char* ptr){  while ( *ptr == ' ' ) ptr++;  if ( *ptr == '-' ) ptr++;  else    if ( *ptr == '+' ) ptr++;  //  bool bSymbol = false;  while ( *ptr )  {    if ( *ptr == ' ' && bSymbol )    {      while ( *ptr == ' ' ) ptr++;      return *ptr == 0;    }    if ( !('0' <= *ptr && *ptr <= '9') )      return false;    ptr++;    bSymbol = true;  }  return bSymbol;}double Atos(char* ptr){  //static lconv* conv = localeconv();  struct lconv* conv = localeconv();  static char dp = conv->decimal_point[0];  if ( dp != '.' )  {    char* p = ptr;    while ( *p )    {      if ( *p == '.' ) *p = dp;      p++;    }  }  char* p = ptr;  while ( *p )  {    if ( *p == 'ю' || *p == 'Ю' ) *p = dp;    p++;  }  return atof(ptr);}//-----------------------------------------------------------------------------double atos(const char* ptr){  //static lconv* conv = localeconv();  struct lconv* conv = localeconv();  static char dp = conv->decimal_point[0];  if ( dp != '.' )  {    const char* p = strchr( ptr, '.' );    if ( p != NULL )    {      int dl = lstrlen(ptr);      if ( dl >= 1024 ) return DBL_MAX;      char str[1024];      lstrcpy( str, ptr );      return Atos( str );    }  }  return atof(ptr);}